SELECT COUNT(*) FROM "title" AS v1, "infoVertex" AS v2, "infoIdxVertex" AS v3, "title_infoEdge_infoVertex" AS e1, "title_keywordEdge_keyword" AS e2, "title_infoEdge_infoIdxVertex" AS e3 WHERE e1.src = v1.id AND e1.dst = v2.id AND e2.src = v1.id AND e3.src = v1.id AND e3.dst = v3.id AND v1."production_year" > 2010 AND v1."kind_id" = 1 AND v2."info_type_id" = 8 AND v3."info_type_id" = 101;
